-- Leads QRS (Quotation Retrieval System) - SQL Server schema.
-- Applied automatically when the app first connects (src/server/db.server.ts), after creating
-- the database if needed. Safe to re-run: every object is created only if it does not exist.
-- Separate batches with a line containing only GO. To apply by hand:
--   sqlcmd -S <server> -U <user> -P <password> -d new_leads_qrs -i database/schema.sql
--
-- Ids are short strings generated by the app (see uid() in src/lib/store.tsx).

SET NOCOUNT ON;

-- Accounts. role: Admin (add/edit/delete) or User (view only).
IF OBJECT_ID(N'dbo.users', N'U') IS NULL
CREATE TABLE dbo.users (
  id            NVARCHAR(40)  NOT NULL CONSTRAINT pk_users PRIMARY KEY,
  username      NVARCHAR(100) NOT NULL CONSTRAINT uq_users_username UNIQUE,
  name          NVARCHAR(200) NOT NULL,
  password_hash NVARCHAR(256) NOT NULL,
  role          NVARCHAR(10)  NOT NULL CONSTRAINT ck_users_role CHECK (role IN (N'Admin', N'User')),
  created_at    DATETIME2(3)  NOT NULL CONSTRAINT df_users_created_at DEFAULT SYSUTCDATETIME()
);

-- Login sessions. token_hash is the SHA-256 of the random token kept in the browser cookie.
IF OBJECT_ID(N'dbo.sessions', N'U') IS NULL
CREATE TABLE dbo.sessions (
  token_hash CHAR(64)     NOT NULL CONSTRAINT pk_sessions PRIMARY KEY,
  user_id    NVARCHAR(40) NOT NULL
    CONSTRAINT fk_sessions_user REFERENCES dbo.users(id) ON DELETE CASCADE,
  expires_at DATETIME2(3) NOT NULL,
  created_at DATETIME2(3) NOT NULL CONSTRAINT df_sessions_created_at DEFAULT SYSUTCDATETIME()
);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'ix_sessions_user_id')
  CREATE INDEX ix_sessions_user_id ON dbo.sessions(user_id);

-- Uploaded files (quotation PDFs). Attachments refer to a file by its path.
IF OBJECT_ID(N'dbo.files', N'U') IS NULL
CREATE TABLE dbo.files (
  path         NVARCHAR(400)  NOT NULL CONSTRAINT pk_files PRIMARY KEY,
  file_name    NVARCHAR(260)  NOT NULL,
  content_type NVARCHAR(200)  NOT NULL,
  data         VARBINARY(MAX) NOT NULL,
  created_at   DATETIME2(3)   NOT NULL CONSTRAINT df_files_created_at DEFAULT SYSUTCDATETIME()
);

-- Group companies; code prefixes quotation numbers (e.g. LDS-0001).
IF OBJECT_ID(N'dbo.companies', N'U') IS NULL
CREATE TABLE dbo.companies (
  id    NVARCHAR(40)  NOT NULL CONSTRAINT pk_companies PRIMARY KEY,
  name  NVARCHAR(200) NOT NULL,
  code  NVARCHAR(20)  NOT NULL,
  color NVARCHAR(40)  NOT NULL CONSTRAINT df_companies_color DEFAULT N''
);

IF OBJECT_ID(N'dbo.clients', N'U') IS NULL
CREATE TABLE dbo.clients (
  id     NVARCHAR(40)  NOT NULL CONSTRAINT pk_clients PRIMARY KEY,
  name   NVARCHAR(300) NOT NULL,
  email  NVARCHAR(320) NOT NULL CONSTRAINT df_clients_email DEFAULT N'',
  mobile NVARCHAR(100) NOT NULL CONSTRAINT df_clients_mobile DEFAULT N''
);

IF OBJECT_ID(N'dbo.projects', N'U') IS NULL
CREATE TABLE dbo.projects (
  id        NVARCHAR(40)  NOT NULL CONSTRAINT pk_projects PRIMARY KEY,
  client_id NVARCHAR(40)  NOT NULL CONSTRAINT fk_projects_client REFERENCES dbo.clients(id),
  name      NVARCHAR(300) NOT NULL,
  poc_name  NVARCHAR(200) NOT NULL CONSTRAINT df_projects_poc_name DEFAULT N'',
  poc_email NVARCHAR(320) NOT NULL CONSTRAINT df_projects_poc_email DEFAULT N'',
  poc_phone NVARCHAR(100) NOT NULL CONSTRAINT df_projects_poc_phone DEFAULT N''
);

-- Business development managers (a quotation is "prepared for" one of them).
IF OBJECT_ID(N'dbo.bdms', N'U') IS NULL
CREATE TABLE dbo.bdms (
  id    NVARCHAR(40)  NOT NULL CONSTRAINT pk_bdms PRIMARY KEY,
  name  NVARCHAR(200) NOT NULL,
  email NVARCHAR(320) NOT NULL CONSTRAINT df_bdms_email DEFAULT N''
);

-- Staff master list (a quotation is "prepared by" one of them, stored by name).
IF OBJECT_ID(N'dbo.preparers', N'U') IS NULL
CREATE TABLE dbo.preparers (
  id   NVARCHAR(40)  NOT NULL CONSTRAINT pk_preparers PRIMARY KEY,
  name NVARCHAR(200) NOT NULL
);

IF OBJECT_ID(N'dbo.quotations', N'U') IS NULL
CREATE TABLE dbo.quotations (
  id              NVARCHAR(40)   NOT NULL CONSTRAINT pk_quotations PRIMARY KEY,
  number          NVARCHAR(100)  NOT NULL,
  company_id      NVARCHAR(40)   NOT NULL CONSTRAINT fk_quotations_company REFERENCES dbo.companies(id),
  client_id       NVARCHAR(40)   NOT NULL CONSTRAINT fk_quotations_client REFERENCES dbo.clients(id),
  project_id      NVARCHAR(40)   NOT NULL CONSTRAINT fk_quotations_project REFERENCES dbo.projects(id),
  site_reference  NVARCHAR(300)  NOT NULL CONSTRAINT df_quotations_site_reference DEFAULT N'',
  prepared_for_id NVARCHAR(40)   NOT NULL CONSTRAINT df_quotations_prepared_for_id DEFAULT N'',
  prepared_by     NVARCHAR(200)  NOT NULL CONSTRAINT df_quotations_prepared_by DEFAULT N'',
  note1           NVARCHAR(MAX)  NOT NULL CONSTRAINT df_quotations_note1 DEFAULT N'',
  note2           NVARCHAR(MAX)  NOT NULL CONSTRAINT df_quotations_note2 DEFAULT N'',
  status          NVARCHAR(20)   NOT NULL CONSTRAINT df_quotations_status DEFAULT N'Pending'
    CONSTRAINT ck_quotations_status CHECK (status IN (N'Pending', N'Successful', N'Failed')),
  fail_reason     NVARCHAR(MAX)  NOT NULL CONSTRAINT df_quotations_fail_reason DEFAULT N'',
  amount          DECIMAL(18, 2) NOT NULL CONSTRAINT df_quotations_amount DEFAULT 0,
  created_at      DATETIME2(3)   NOT NULL CONSTRAINT df_quotations_created_at DEFAULT SYSUTCDATETIME()
);

-- Documents attached to a quotation; path is a dbo.files path.
IF OBJECT_ID(N'dbo.attachments', N'U') IS NULL
CREATE TABLE dbo.attachments (
  id           NVARCHAR(40)  NOT NULL CONSTRAINT pk_attachments PRIMARY KEY,
  quotation_id NVARCHAR(40)  NOT NULL
    CONSTRAINT fk_attachments_quotation REFERENCES dbo.quotations(id) ON DELETE CASCADE,
  name         NVARCHAR(260) NOT NULL,
  category     NVARCHAR(100) NOT NULL CONSTRAINT df_attachments_category DEFAULT N'',
  path         NVARCHAR(400) NOT NULL,
  size         INT           NOT NULL CONSTRAINT df_attachments_size DEFAULT 0,
  uploaded_at  DATETIME2(3)  NOT NULL CONSTRAINT df_attachments_uploaded_at DEFAULT SYSUTCDATETIME(),
  uploaded_by  NVARCHAR(200) NOT NULL CONSTRAINT df_attachments_uploaded_by DEFAULT N''
);

-- Who viewed, previewed or downloaded which quotation.
IF OBJECT_ID(N'dbo.access_logs', N'U') IS NULL
CREATE TABLE dbo.access_logs (
  id           NVARCHAR(40)  NOT NULL CONSTRAINT pk_access_logs PRIMARY KEY,
  quotation_id NVARCHAR(40)  NOT NULL
    CONSTRAINT fk_access_logs_quotation REFERENCES dbo.quotations(id) ON DELETE CASCADE,
  user_name    NVARCHAR(200) NOT NULL,
  user_id      NVARCHAR(40)  NULL,
  action       NVARCHAR(20)  NOT NULL
    CONSTRAINT ck_access_logs_action CHECK (action IN (N'View', N'Preview', N'Download')),
  at           DATETIME2(3)  NOT NULL CONSTRAINT df_access_logs_at DEFAULT SYSUTCDATETIME()
);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'ix_access_logs_at')
  CREATE INDEX ix_access_logs_at ON dbo.access_logs(at);

IF OBJECT_ID(N'dbo.mail_settings', N'U') IS NULL
CREATE TABLE dbo.mail_settings (
  id           NVARCHAR(40)  NOT NULL CONSTRAINT pk_mail_settings PRIMARY KEY,
  from_address NVARCHAR(320) NOT NULL,
  to_address   NVARCHAR(320) NOT NULL,
  subject      NVARCHAR(300) NOT NULL,
  threshold    INT           NOT NULL CONSTRAINT df_mail_settings_threshold DEFAULT 5
);
GO

-- Starting data from the original system, added once to an empty database. There are no
-- default accounts: the sign-in page asks for the first administrator.
